import React from "react";
import { Link, graphql } from "gatsby";
import { GatsbyImage, getImage } from "gatsby-plugin-image";
import { ArrowRight, Code2 } from "lucide-react";
import { postPath } from "../lib/content.cjs";
import { withSizes } from "../lib/images";
export const fragment = graphql`
  fragment PostCardData on Mdx {
    id
    excerpt(pruneLength: 160)
    fields {
      readingMinutes
    }
    frontmatter {
      draft
      series
      seriesTitle
      seriesOrder
      title
      slug
      description
      date(formatString: "MMM D, YYYY")
      tags
      featuredImage {
        childImageSharp {
          gatsbyImageData(width: 800, aspectRatio: 1.6, placeholder: BLURRED)
        }
      }
    }
  }
`;
// Rendered cover widths for each layout.
const coverSizes = {
  grid: "(min-width: 1184px) 357px, (min-width: 761px) calc((100vw - 96px) / 3), (min-width: 481px) calc((100vw - 60px) / 2), calc(100vw - 32px)",
  archive: "(min-width: 901px) 240px, (min-width: 601px) 180px, calc(100vw - 64px)",
};
export default function PostCard({ nodes = [], variant = "grid", headingLevel = "h2" }) {
  const Heading = headingLevel;
  return (
    <div className={`post-grid${variant === "archive" ? " post-archive" : ""}`}>
      {nodes.map((node, index) => {
        const post = node.frontmatter;
        const image = withSizes(getImage(post.featuredImage), coverSizes[variant]);
        return (
          <article
            className="post-card enter"
            style={{ "--delay": `${index * 65}ms` }}
            key={node.id}
          >
            <Link className="post-card-link" to={postPath(post.slug)}>
              <div className="card-image">
                {image ? (
                  <GatsbyImage image={image} alt="" />
                ) : (
                  <div className="image-placeholder">
                    <Code2 size={44} aria-hidden="true" />
                  </div>
                )}
                <span className="image-arrow" aria-hidden="true">
                  <ArrowRight size={18} />
                </span>
              </div>
              <div className="card-body">
                <div className="card-category">
                  {(post.tags || []).slice(0, 2).join(" / ") || "Field notes"}
                </div>
                {post.draft && <span className="draft-label">Draft</span>}
                {post.series && <p className="series-label">{post.seriesTitle} · Part {post.seriesOrder}</p>}
                <Heading>{post.title}</Heading>
                <p>{post.description || node.excerpt}</p>
                <div className="card-meta">
                  <span>{post.date}</span>
                  <span className="meta-dot" />
                  <span>{node.fields.readingMinutes} min read</span>
                </div>
              </div>
            </Link>
          </article>
        );
      })}
    </div>
  );
}
