// Tell the browser how wide an image renders, so it picks the smallest file.
export function withSizes(image, sizes) {
  if (!image) return image;
  return {
    ...image,
    images: {
      ...image.images,
      fallback: image.images.fallback && { ...image.images.fallback, sizes },
      sources: image.images.sources?.map((source) => ({ ...source, sizes })),
    },
  };
}
